"<!doctype html><html lang='vi'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><meta name='color-scheme' content='dark'><title>AUBOT | Chẩn đoán</title><link rel='stylesheet' href='/ui.css?v=5'><style>"
".diag{display:grid;grid-template-columns:minmax(270px,.7fr) minmax(0,1.3fr);gap:14px}.rows{border-top:1px solid var(--line2)}.row{display:flex;justify-content:space-between;gap:14px;min-height:42px;align-items:center;border-bottom:1px solid var(--line2)}.row span{color:var(--muted)}.id-grid{display:grid;grid-template-columns:repeat(8,minmax(44px,1fr));gap:7px;min-width:420px}.id-wrap{overflow-x:auto}.laser{position:relative;min-height:52px;border:1px solid var(--line2);border-radius:9px;background:var(--glass2);color:var(--muted);font-weight:800}.laser:after{content:'';position:absolute;right:6px;top:6px;width:7px;height:7px;border-radius:50%;background:#526079}.laser.online{border-color:rgba(52,211,153,.45);background:rgba(20,53,48,.75);color:#bbf7d0}.laser.online:after{background:var(--success)}.laser.warn{border-color:rgba(251,191,36,.55);background:rgba(64,47,20,.8);color:#fde68a}.laser.warn:after{background:var(--warning)}.laser.selected{outline:3px solid rgba(57,205,248,.45)}.laser:disabled{cursor:not-allowed}.empty{display:grid;place-items:center;min-height:190px;color:var(--muted)}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.metric{padding:10px;border:1px solid var(--line2);border-radius:9px;background:var(--glass2)}.metric small{display:block;color:var(--muted)}.metric b{display:block;margin-top:3px}@media(max-width:900px){.diag{grid-template-columns:1fr}}@media(max-width:540px){.metrics{grid-template-columns:1fr}}</style></head><body data-page='tech'><div class='shell'>"
"<header class='hero'><div class='brand'><img class='logo' src='/logo.png' alt='AUBOT'><div><div class='eyebrow'>AUBOT · WAREHOUSE GATEWAY</div><h1>Chẩn đoán hệ thống</h1><p>CAN và cảm biến Laser · chỉ đọc</p></div></div><div data-app-user></div></header><div data-system-bar></div><nav class='nav' data-app-nav></nav>"
"<main class='diag'><section class='card'><header class='card-head'><span class='step'>01</span><h2>Tổng quan</h2></header><div class='rows'><div class='row'><span>CAN</span><b id='can'>--</b></div><div class='row'><span>Laser online</span><b id='online'>0</b></div><div class='row'><span>Khung RX</span><b id='rx'>0</b></div><div class='row'><span>TX thất bại</span><b id='tx'>0</b></div><div class='row'><span>RX bỏ qua / tràn</span><b id='drop'>0 / 0</b></div><div class='row'><span>Lỗi bus</span><b id='bus'>0</b></div><div class='row'><span>Tower</span><b id='tower'>--</b></div></div></section>"
"<section class='card'><header class='card-head'><span class='step'>02</span><div><h2>Laser ID 1–64</h2><p class='hint'>Ma trận ID vật lý; không phải vị trí kho hoặc nhóm cấu hình</p></div></header><div class='id-wrap'><div id='grid' class='id-grid'></div></div></section>"
"<section class='card'><header class='card-head'><span class='step'>03</span><h2>Chi tiết Laser</h2></header><div id='empty' class='empty'>Chọn một Laser online để xem dữ liệu</div><div id='detail' class='rows hidden'></div></section>"
"<section class='card'><header class='card-head'><span class='step'>04</span><h2>CAN nâng cao</h2></header><details id='advanced'><summary>Mở bộ đếm CAN chi tiết</summary><div class='details-body'><div id='advancedLoading' class='hint'>Dữ liệu chỉ tải khi mục này được mở.</div><div id='metrics' class='metrics hidden'></div></div></details></section></main><footer class='toolbar' style='margin-top:14px'><span id='updated'>Đang kết nối…</span><button class='btn ghost' id='pause'>Tạm dừng</button></footer></div>"
"<script src='/ui.js?v=5'></script><script>const $=x=>document.getElementById(x),fmt=x=>Number(x||0).toLocaleString('vi-VN'),canVi=s=>({ACTIVE:'HOẠT ĐỘNG',WARNING:'CẢNH BÁO',PASSIVE:'THỤ ĐỘNG','BUS-OFF':'MẤT MẠNG',STOPPED:'ĐÃ DỪNG'}[s]||s),warnVi=s=>({CLEAR:'KHÔNG CÓ HÀNG',NORMAL:'CÓ HÀNG',EMERGENCY:'CÓ HÀNG'}[s]||'CHƯA XÁC ĐỊNH');let selected=0,paused=false,summaryTimer,gridTimer,detailTimer,canTimer;const cells=Array(65),state=Array(65);for(let id=1;id<=64;id++){const b=document.createElement('button');b.className='laser';b.type='button';b.textContent=id;b.disabled=true;b.onclick=()=>select(id);$('grid').append(b);cells[id]=b}function later(fn,ms){return setTimeout(fn,document.hidden?10000:ms)}async function summary(){clearTimeout(summaryTimer);if(paused)return;try{const d=await gw.fetchJson('/api/tech/summary');$('can').textContent=canVi(d.can_state);$('online').textContent=d.laser_online;$('rx').textContent=fmt(d.rx_frames);$('tx').textContent=fmt(d.tx_fail);$('drop').textContent=fmt(d.rx_rejected)+' / '+fmt(d.rx_dropped);$('bus').textContent=fmt(d.bus_errors);$('tower').textContent=d.output.red?'ĐỎ':d.output.yellow?'VÀNG':d.output.green?'XANH':'TẮT';$('updated').textContent='Cập nhật '+new Date().toLocaleTimeString('vi-VN')}catch(e){}summaryTimer=later(summary,1000)}async function lasers(){clearTimeout(gridTimer);if(paused)return;try{const d=await gw.fetchJson('/api/tech/lasers');const next=Array(65);for(const n of d.lasers||[])next[n.id]=n;for(let id=1;id<=64;id++){const n=next[id],b=cells[id],cls='laser '+(n&&n.online?(n.warn!=='CLEAR'?'warn':'online'):'')+(id===selected?' selected':'');if(b.className!==cls)b.className=cls;b.disabled=!(n&&n.online);b.setAttribute('aria-label','Laser '+id+' '+(n&&n.online?'online':'offline'));state[id]=n}}catch(e){}gridTimer=later(lasers,2500)}function row(k,v){return `<div class='row'><span>${k}</span><b>${v}</b></div>`}async function detail(){clearTimeout(detailTimer);if(paused||!selected)return;if(document.hidden){detailTimer=later(detail,1000);return}try{const d=await gw.fetchJson('/api/tech/laser?id='+selected);$('empty').classList.add('hidden');$('detail').classList.remove('hidden');$('detail').innerHTML=row('Laser ID',d.id)+row('Nhóm Laser',d.group)+row('Kết nối',d.online?'ONLINE':'OFFLINE')+row('Nhận gần nhất',fmt(d.last_seen_ms)+' ms')+row('Dữ liệu',d.status_valid?'HỢP LỆ':'CHƯA HỢP LỆ')+row('Trạng thái kho',warnVi(d.warn))+row('Khoảng cách',fmt(d.distance_mm)+' mm')+row('Khẩn cấp',fmt(d.emergency_mm)+' mm')+row('Mặt nạ hàng / cột',d.row+' / '+d.column)+row('Phát hiện',d.proximity?'ĐANG BẬT':'ĐANG TẮT')+row('Cấu hình',d.config_state)}catch(e){}detailTimer=later(detail,1000)}function select(id){selected=id;for(let i=1;i<=64;i++)cells[i].classList.toggle('selected',i===id);detail()}function metric(k,v){return `<div class='metric'><small>${k}</small><b>${fmt(v)}</b></div>`}async function advanced(){clearTimeout(canTimer);if(paused||!$('advanced').open)return;if(document.hidden){canTimer=later(advanced,3000);return}try{const d=await gw.fetchJson('/api/tech/can');$('advancedLoading').classList.add('hidden');$('metrics').classList.remove('hidden');$('metrics').innerHTML=metric('TX thành công',d.tx_ok)+metric('TX thất bại',d.tx_fail)+metric('TX error',d.tx_error)+metric('RX error',d.rx_error)+metric('RX loại bỏ',d.rx_rejected)+metric('RX tràn',d.rx_dropped)+metric('Sự kiện lỗi',d.error_events)+metric('Mất phân xử',d.arbitration_lost)+metric('Lỗi bit',d.bit_errors)+metric('Lỗi định dạng',d.form_errors)+metric('Lỗi nhồi bit',d.stuff_errors)+metric('Lỗi ACK',d.ack_errors)+metric('ID gần nhất',d.last_id)+metric('DLC gần nhất',d.last_dlc)}catch(e){}canTimer=later(advanced,3000)}$('advanced').ontoggle=()=>{if($('advanced').open)advanced();else clearTimeout(canTimer)};$('pause').onclick=()=>{paused=!paused;$('pause').textContent=paused?'Tiếp tục':'Tạm dừng';if(!paused){summary();lasers();detail();advanced()}};document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!paused){summary();lasers();detail();advanced()}});summary();lasers()</script></body></html>";
